from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    print("Testing event with newline...")
    try:
        ServerSentEvent(data="hello", event="greeting\nnewline")
        print("FAILED: event with newline should have raised ValidationError")
    except ValidationError as e:
        print(f"PASSED: caught expected ValidationError for event: {e}")

    print("\nTesting id with newline...")
    try:
        ServerSentEvent(data="hello", id="1\nnewline")
        print("FAILED: id with newline should have raised ValidationError")
    except ValidationError as e:
        print(f"PASSED: caught expected ValidationError for id: {e}")

    print("\nTesting id with null character...")
    try:
        ServerSentEvent(data="hello", id="1\0null")
        print("FAILED: id with null character should have raised ValidationError")
    except ValidationError as e:
        print(f"PASSED: caught expected ValidationError for null char: {e}")

    print("\nTesting valid SSE event...")
    try:
        ServerSentEvent(data="hello", event="greeting", id="1")
        print("PASSED: valid event accepted")
    except ValidationError as e:
        print(f"FAILED: valid event raised ValidationError: {e}")

if __name__ == "__main__":
    test_sse_validation()

